def calcular_frete(peso_kg: float, regiao: str, valor_pedido: float,
                   cupom: str | None = None, expresso: bool = False) -> float:
    # 1. Validação
    if not (peso_kg > 0 and peso_kg <= 30):
        raise ValueError("peso_kg deve ser > 0 e <= 30")
    if regiao not in ("S", "SE", "CO", "NE", "N"):
        raise ValueError("região inválida")
    if valor_pedido < 0:
        raise ValueError("valor_pedido deve ser >= 0")

    # 2. Tarifa base por peso
    if peso_kg <= 1:
        base = Decimal("12.00")
    elif peso_kg <= 5:
        fracoes = math.ceil(peso_kg - 1)
        base = Decimal("12.00") + Decimal(fracoes) * Decimal("3.50")
    else:
        fracoes = math.ceil(peso_kg - 5)
        base = Decimal("26.00") + Decimal(fracoes) * Decimal("2.80")

    # 3. Multiplicador regional
    if regiao in ("S", "SE"):
        valor = base * Decimal("1.00")
    elif regiao == "CO":
        valor = base * Decimal("1.20")
    elif regiao == "NE":
        valor = base * Decimal("1.35")
    else:  # N
        valor = base * Decimal("1.50")

    # 4. Expresso
    if expresso:
        valor *= Decimal("1.40")

    # 5. Frete grátis (ignora cupom, mesmo se inválido)
    if valor_pedido >= 299.90 and not expresso and regiao in ("S", "SE", "CO"):
        return 0.0

    # 6. Cupons (case-insensitive)
    if cupom is not None and cupom != "":
        cupom_superior = cupom.upper()
        if cupom_superior == "FRETE10":
            valor *= Decimal("0.90")
