        else:
            raise ValueError("cupom inválido")

    # 7. Frete mínimo
    if valor < Decimal("9.90"):
        valor = Decimal("9.90")

    # 8. Arredondimento ROUND_HALF_UP
    resultado = valor.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return float(resultado)

